const {seg,eo,eio,lerp}=kit;
kit.scene('parallel',{
 init(kit){
  this.root=W.mount(kit,'parallel');
  kit.css('.parallel-lane{position:absolute;left:112px;width:1696px;display:flex;align-items:center;height:142px;border-bottom:2px solid color-mix(in srgb,var(--main) 13%,var(--ground))}.parallel-who{width:300px;display:flex;align-items:center;gap:22px;font-size:43px;font-weight:600}.parallel-badge{width:56px;height:56px;border-radius:50%;background:color-mix(in srgb,var(--main) 9%,var(--ground));display:grid;place-items:center;color:var(--main);font-size:28px}.parallel-road{position:absolute;left:345px;right:570px;height:3px;background:color-mix(in srgb,var(--main) 17%,var(--ground))}.parallel-packet{position:absolute;left:0;top:-6px;width:62px;height:15px;border-radius:8px;background:var(--main)}.parallel-task{position:absolute;left:350px;top:12px;font-size:30px;color:color-mix(in srgb,var(--second) 70%,var(--ground))}.parallel-dest{position:absolute;right:0;width:520px;display:flex;flex-direction:column;gap:9px}.parallel-dest strong{font-size:43px;font-weight:600}.parallel-dest span{font-size:27px;color:color-mix(in srgb,var(--second) 65%,var(--ground))}.parallel-owner{display:inline-block;width:13px;height:13px;border-radius:50%;background:var(--main);margin-right:14px}');
  this.root.append(kit.h('<div class="words parallel-heading" style="left:112px;top:195px;width:1650px"><h2 class="line">不同目标，各自并行。</h2></div>'));
  const rows=[['A','查资料','资料 Profile','由 Agent A 控制'],['B','验收网页','测试 Profile','由 Agent B 控制'],['C','检查应用','独立 Electron 应用','由 Agent C 控制']];
  rows.forEach((r,i)=>this.root.append(kit.h('<div class="parallel-lane" style="top:'+(365+i*172)+'px"><div class="parallel-who"><span class="parallel-badge">'+r[0]+'</span><span>Agent '+r[0]+'</span></div><span class="parallel-task">'+r[1]+'</span><div class="parallel-road"><i class="parallel-packet"></i></div><div class="parallel-dest"><strong>'+r[2]+'</strong><span><i class="parallel-owner"></i>'+r[3]+'</span></div></div>')));
  this.root.append(kit.h('<div class="words parallel-note" style="left:112px;top:900px;width:1650px;flex-direction:row;align-items:center;gap:22px"><span class="pill" style="border-color:var(--accent);color:var(--accent)"><span>目标已占用</span></span><p style="font-size:33px">同一目标的额外请求，停止并提示。</p></div>'));
  this.heading=this.root.querySelector('.parallel-heading');this.rows=[...this.root.querySelectorAll('.parallel-lane')];this.packets=[...this.root.querySelectorAll('.parallel-packet')];this.note=this.root.querySelector('.parallel-note');
  this.root.querySelector('.foot').style.display='none';
 },
 render(t){
  W.reveal(this.heading,t,-.5,22,.8);
  this.rows.forEach((row,i)=>W.reveal(row,t,.2+i*.24,32,.65));
  this.packets.forEach((el,i)=>{const p=((Math.max(0,t-.5)+i*.42)%(2.4+i*.2))/(2.4+i*.2);el.style.transform='translateX('+(p*688)+'px)';el.style.opacity=seg(t,.5+i*.2,1+i*.2)*(.3+.7*Math.sin(Math.PI*p));});
  W.reveal(this.note,t,3.35,24,.65);
  this.heading.style.transform='translateY('+lerp(10,-3,eo(seg(t,-.3,7)))+'px)';
  W.progress(this.root,t,4);
 }
});
